// Original v1 named schematics. Preserve these semantics for frozen v1 picture sources.
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function bean(){return `<path d="M160 222V38" stroke="#466c3d" stroke-width="9" stroke-linecap="round"/><path d="M159 176Q97 96 42 133Q57 199 159 176ZM162 176Q223 96 278 133Q263 199 162 176ZM159 113Q105 45 61 69Q73 130 159 113ZM162 113Q215 45 259 69Q247 130 162 113Z" fill="#a9ca87" stroke="#466c3d" stroke-width="2.5"/><path d="M159 176l-89-30m92 30l89-30m-92-33l-73-32m76 32l73-32" fill="none" stroke="#70945b" stroke-width="2"/><text x="160" y="249" text-anchor="middle" font-size="15" fill="#183f39">Broad bean · leaves and living stem</text>`;}
function aphid(){const legs=Array.from({length:3},(_,i)=>['top','bottom'].map(side=>{const sign=side==='top'?-1:1,x=112+i*16,kx=99+i*28,fx=84+i*43;return `<g data-food-leg="${side}-${i+1}"><path d="M${x} ${136+sign*12}L${kx} ${136+sign*38}L${fx} ${136+sign*63}" fill="none" stroke="#35483b" stroke-width="5" stroke-linecap="round"/><circle cx="${kx}" cy="${136+sign*38}" r="3" fill="#f0f4e9" stroke="#35483b" stroke-width="1.5"/></g>`;}).join('')).join('');return `<path d="M43 27V222" stroke="#688849" stroke-width="9" stroke-linecap="round"/><path d="M44 185Q17 158 18 137Q45 143 44 185Z" fill="#abc886" stroke="#688849" stroke-width="2"/>${legs}<path d="M125 117C154 83 219 91 235 133C249 176 195 193 151 170L127 157Z" fill="#515855" stroke="#243e33" stroke-width="3"/><ellipse cx="120" cy="138" rx="26" ry="24" fill="#58625b" stroke="#243e33" stroke-width="2"/><ellipse cx="91" cy="138" rx="18" ry="20" fill="#58625b" stroke="#243e33" stroke-width="2"/><g data-food-appendage="antennae" stroke="#a06c27" stroke-width="2.5" fill="none"><path d="M84 123L69 105L56 101M92 121L91 96L81 85"/></g><path data-food-mouthpart="sap" d="M77 144L44 154" fill="none" stroke="#754e2c" stroke-width="2"/><g data-food-appendage="cornicles" fill="#8b8d83" stroke="#3e5144" stroke-width="2"><path d="M210 113l14-12 5 6-14 12ZM216 162l17 8-4 7-17-9Z"/></g><path d="M245 103h35m-42 70h42" stroke="#8b8d83" stroke-width="1"/><text x="281" y="138" text-anchor="end" font-size="12" fill="#52675e">rear tubes</text><text x="160" y="243" text-anchor="middle" font-size="14" fill="#183f39">Wingless nymph · fine mouthpart touches stem</text>`;}
function ladybirdLarva(){const legs=Array.from({length:3},(_,i)=>['left','right'].map(side=>{const sign=side==='left'?-1:1,y=79+i*17;return `<g data-food-leg="${side}-${i+1}"><path d="M${160+sign*24} ${y}L${160+sign*43} ${y+6}L${160+sign*62} ${y+19}" fill="none" stroke="#364a3d" stroke-width="5" stroke-linecap="round"/><circle cx="${160+sign*43}" cy="${y+6}" r="3" fill="#f0f4e9" stroke="#364a3d" stroke-width="1.5"/></g>`;}).join('')).join('');return `${legs}<path d="M136 67Q160 56 184 67L190 98L183 132L176 166L169 200L160 218L151 200L144 166L137 132L130 98Z" fill="#818b87" stroke="#354b40" stroke-width="2.5"/>${[86,110,135,160,184].map(y=>`<path d="M${y<115?134:y<165?141:149} ${y}Q160 ${y+6} ${y<115?186:y<165?179:171} ${y}" fill="none" stroke="#4e6256" stroke-width="2"/>`).join('')}<ellipse cx="160" cy="53" rx="20" ry="19" fill="#53645a" stroke="#354b40" stroke-width="2"/>${[93,119,144,169].map((y,i)=>`<g data-food-orange-pair="${i+1}"><ellipse cx="${145+i*2}" cy="${y}" rx="5" ry="7" fill="#d88e42" stroke="#9c642d" stroke-width="1"/><ellipse cx="${175-i*2}" cy="${y}" rx="5" ry="7" fill="#d88e42" stroke="#9c642d" stroke-width="1"/></g>`).join('')}<path d="M151 38l-5-8m23 8l5-8" stroke="#5a6d5b" stroke-width="2"/><text x="160" y="244" text-anchor="middle" font-size="14" fill="#183f39">Seven-spot ladybird larva · no adult wing cases</text>`;}
const draw={bean,aphid,'ladybird-larva':ladybirdLarva};
export function foodLinkDiagram(card,inline=false){const d=card?.drawing,tag=inline?'span':'figure';if(d?.version!==1||d.kind!==card?.id||!Object.hasOwn(draw,d.kind)){const box=inline?'span':'div',line=inline?'span':'p';return `<${box} class="food-picture-unavailable"><strong>${esc(card?.label||'Saved picture')}</strong> <${line}>This saved picture version is unavailable. Its original description remains:</${line}> <${line}>${esc(card?.pictureText||'')}</${line}></${box}>`;}return `<${tag} class="food-card-diagram" data-food-drawing="${d.kind}" data-food-drawing-version="1"><svg viewBox="0 0 320 265" ${inline?'aria-hidden="true" focusable="false"':`role="img" aria-label="${esc(card.pictureText)}"`}><rect x="1" y="1" width="318" height="263" rx="18" fill="#f0f4e9"/>${draw[d.kind]()}</svg></${tag}>`;}
